"""Generate the serving API dictionary from the linted SQL files without a database."""

from __future__ import annotations

from pathlib import Path

from analyses import deploy
from model import dictionary
from vs.host.namespace import Namespace
from vs.host.sqlobjects import SqlObject

DICTIONARY_PATH = Path(__file__).resolve().parents[1] / "docs" / "api-dictionary.md"
INTRO = (
    "Generated by `make api-docs` from `sql/api/` and `sql/api_live/`; do not edit. "
    "The deployment checks these object and column comments against the database. "
    "Each view comment begins with its row grain. `Reads` lists its stored source objects.\n\n"
    "`CFB_API` has the stored-data views for the app (`CFB_APP`) and chat (`CFB_MCP`). "
    "Use a literal `AS_OF_SEASON` and `AS_OF_WEEK_SEQ` when reading a point-grain view. "
    "`CFB_API_LIVE.QUOTA` is app-only and reads the free CFBD `/info` endpoint when queried; "
    "deploying the views makes zero CFBD requests. The game preview uses the Phase 6 operator "
    "path because Exasol does not push its required `P_GAME_ID` filter through a view."
)


def _source_path(item: SqlObject) -> str:
    directory = "sql/api_live" if item.schema == Namespace("").api_live_schema else "sql/api"
    return f"{directory}/{item.file}"


def render_dictionary() -> str:
    """Lint and render all installed serving views for the real namespace."""
    api, live = deploy.prepare(Namespace(""))
    return dictionary.generate(
        [*api, *live], title="CFB_API", intro=INTRO, source_path=_source_path
    )


def write_dictionary(path: Path = DICTIONARY_PATH) -> int:
    """Write the checked dictionary and return its view count."""
    rendered = render_dictionary()
    path.write_text(rendered, encoding="utf-8")
    return rendered.count("\n## ") - 1
